{
  "description": "A large quadrupedal hybrid creature shown in right-facing profile against a plain light background, combining the body, fur, and head of a brown bear with the glossy exoskeleton and horn of a rhinoceros beetle. The animal has dense brown fur on its head, muzzle, neck, chest, belly, and limbs, with a bear-like head, black nose, and dark eyes. Over the fur sits an extensive shiny dark brown to black segmented armor that covers the top of the head, the neck, the entire back and sides, the shoulders, hips, and lower legs, with smooth reflective plates, rows of oval openings along the lower edge of the back armor, and spiky ridges on the lower front legs. A single large curved glossy horn rises from the head armor. It stands on four clawed paws with a small furry tail visible at the rear.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head with medium brown fur, lighter tan muzzle, black nose, dark brown eyes and a closed mouth, facing to the right",
      "where": "at the front right end of the body, attached to the neck"
    },
    {
      "part": "horns",
      "looks_like": "one large glossy black curved horn with two small pointed notches on the inner curve, smooth and shiny, tapering to a sharp tip",
      "where": "on top of the head, rising from the dark head plate and arching up and backward then forward over the head"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded furry ears covered in short brown fur, with inner fur visible",
      "where": "on top of the head on either side of the horn base, protruding above the head plates"
    },
    {
      "part": "legs",
      "looks_like": "four thick sturdy legs covered in brown fur and partially encased in dark glossy segmented plates; the front lower legs have rows of sharp spike-like protrusions on the outer edge",
      "where": "underneath the body, two front legs under the chest and two hind legs under the hips, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four large furry paws with long dark curved claws on each toe, brown fur on top and dark pads underneath",
      "where": "at the bottom ends of each leg, flat on the ground"
    },
    {
      "part": "tail",
      "looks_like": "small short furry brown tail with shaggy fur, rounded tip",
      "where": "at the rear left end of the body, just behind the hind leg armor and above the hind feet"
    },
    {
      "part": "plates",
      "looks_like": "extensive dark brown to black glossy segmented exoskeleton plates with smooth shiny surfaces and thin gold-brown seams between segments; includes a helmet-like head plate, layered neck rings, large shoulder and hip shields with oval holes, a multi-segmented back carapace with a row of eight oval openings along the lower side, lighter brown segmented belly plates, and segmented shin guards",
      "where": "covering the top of the head, around the neck, over the entire back and sides from shoulders to rump, over the shoulders and hips, around the lower neck and chest, and around the lower portions of all four legs"
    }
  ],
  "attached_objects": [],
  "animals": ["bear", "rhinoceros beetle"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
